import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {R,SQ,center,cell,height,world,addTile,beginMove,finishMove,step,canPlace,path,total} from '../tile-game-assets/bronze-age-world/tile-game/simulation.mjs';
const {cards}=JSON.parse(fs.readFileSync(new URL('../tile-game-assets/bronze-age-world/tile-game/catalog.json',import.meta.url)));
test('exactly ten types; axial positions roundtrip and shared seams agree',()=>{assert.equal(cards.length,10);for(let q=-3;q<=3;q++)for(let r=-3;r<=3;r++){const c=center(q,r);assert.deepEqual(cell(c.x,c.z),{q,r});const a={q,r,level:0},b={q:q+1,r,level:0};for(let i=0;i<=20;i++){const z=-R/2+i*R/20,x=R*SQ/2;assert.ok(Math.abs(height(a,x,z)-height(b,-x,z))<1e-9);}}});
test('move and cancelled drop preserve inventory, age and work; illegal drops restore pose',()=>{const w=world(),a=addTile(w,'garden',0,0),b=addTile(w,'store',1,0);a.inventory.food=7;a.progress=3;a.age=12;const m=beginMove(w,a.id);for(let i=0;i<60;i++)step(w,cards,1/60);assert.equal(a.age,12);assert.equal(a.progress,3);assert.equal(finishMove(w,m,{q:1,r:0,level:0}),false);assert.equal(a.q,0);assert.equal(a.inventory.food,7);const n=beginMove(w,a.id);assert.ok(finishMove(w,n,{q:-1,r:1,level:0}));assert.equal(a.inventory.food,7);assert.equal(a.progress,3);assert.equal(a.age,12);});
test('stack support, top-first lift, and height-separated connectivity',()=>{const w=world(),a=addTile(w,'garden',0,0),b=addTile(w,'store',0,0,1);assert.equal(canPlace(w,2,0,1),false);assert.equal(beginMove(w,a.id),null);assert.equal(path(w,a,b),null);const m=beginMove(w,b.id);assert.ok(finishMove(w,m,{q:1,r:0,level:0}));assert.equal(path(w,a,b).length,2);});
test('connected recipes consume finite inputs; previews never enter world economy',()=>{const w=world(),a=addTile(w,'garden',0,0),b=addTile(w,'home',1,0);for(let i=0;i<481;i++)step(w,cards,1/60);assert.equal(a.inventory.food,0);assert.equal(b.inventory.comfort,1);assert.equal(total(w),1);assert.equal(w.tiles.length,2);assert.throws(()=>step(w,cards,NaN));});
test('moving connection changes storage access without duplicate delivery',()=>{const w=world(),a=addTile(w,'garden',0,0),b=addTile(w,'store',1,0);for(let i=0;i<481;i++)step(w,cards,1/60);assert.equal(b.inventory.food,1);const n=beginMove(w,b.id);finishMove(w,n,{q:4,r:0,level:0});for(let i=0;i<480;i++)step(w,cards,1/60);assert.equal(b.inventory.food,1);assert.equal(a.inventory.food,1);assert.equal(w.deliveries,1);});
